INSERT INTO public.products (product_id, name, brand, description, price, sizes, image_url, stock_quantity, category, colors_general) VALUES
('KVP007', 'Baskets Adidas Homme Handball Spezial Focus Olive', ' Adidas', 'Découvrez l''alliance parfaite entre héritage sportif et style contemporain avec ces baskets signées Adidas. Inspirées des modèles emblématiques des années 70, elles séduisent par leur élégante palette de couleurs Focus Olive, Fox Brown et Gum, offrant une touche sophistiquée à toutes vos tenues. Leur dessus en cuir premium assure une allure raffinée et une grande durabilité, tandis que la doublure synthétique garantit un confort optimal tout au long de la journée. La semelle extérieure en caoutchouc robuste procure une excellente adhérence, que ce soit en ville ou lors de vos activités sportives. Les célèbres 3-Stripes sur le côté et le branding distinctif sur la languette témoignent de l''authenticité et du savoir-faire de la marque Adidas. Grâce à leur système de laçage précis, ces baskets s''ajustent parfaitement à votre pied pour un maintien sur-mesure. Parfaitement adaptées aux hommes à la recherche d''une basket polyvalente, elles incarnent à la fois l''histoire, la qualité et le confort. Optez pour un modèle intemporel qui traverse les tendances et affirmez votre style avec une pièce incontournable de la collection Adidas.', '110', '["40 2/3", "41 1/3", "42 2/3", "43 1/3", "44 2/3", "45 1/3", "46 2/3", "40", "42", "44", "46"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_men_handball_spezial_focus_olive_fox_brown_gum_12.jpg', '19', 'Homme', '[''noir'', ''marron'']'),
('KVP008', 'Baskets Adidas Femme Gazelle Indoor Pure Teal', ' Adidas', 'Découvrez une paire de baskets qui incarne parfaitement l''alliance entre l''élégance rétro et l''innovation moderne. Avec sa couleur Pure Teal rehaussée de touches Off White et Gold Metallic, ce modèle séduit par son esthétique audacieuse et raffinée. La marque Adidas, reconnue mondialement pour son savoir-faire et son souci du détail, propose ici une chaussure dont le dessus en cuir et en matières synthétiques assure durabilité et style. La présence des emblématiques 3-Stripes et du logo doré sur le côté souligne l''authenticité et l''héritage sportif du modèle, tandis que la semelle cupsole en caoutchouc garantit une adhérence fiable au quotidien. La doublure synthétique et textile offre un confort optimal, même lors d''une utilisation prolongée. Initialement conçue pour l''entraînement en intérieur, cette basket est aujourd''hui un incontournable de la mode urbaine, idéale pour les femmes à la recherche d''une touche sportive et sophistiquée. Parfaite pour compléter aussi bien une tenue décontractée qu''un look plus travaillé, elle séduira celles qui souhaitent affirmer leur style tout en bénéficiant de la qualité et du confort légendaires d''Adidas. Convient à toutes celles qui veulent conjuguer performance, élégance et modernité dans une seule paire de baskets.', '120', '["36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "36", "38", "40"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_gazelle_indoor_pure_teal_off_white_gold_metallic_7.jpg', '21', 'Femme', '[''menthol'', ''or'', ''bleu'', ''blanc'']'),
('KVP009', 'Baskets Adidas Femme Gazelle Bold Ash Green', ' Adidas', 'Offrant une alliance parfaite entre héritage et modernité, cette paire de baskets pour femmes séduit par son design rétro inspiré des modèles iconiques des années 70. La marque Adidas propose ici une création raffinée, dotée d''un dessus en cuir et matières synthétiques, dans une élégante combinaison de couleurs Ash Green, Off White et Gum. Les célèbres 3 bandes, accompagnées de l''inscription dorée sur le côté, témoignent de l''authenticité et du prestige de la marque. La doublure synthétique assure un confort optimal tout au long de la journée, tandis que la semelle extérieure en gomme garantit une excellente adhérence et une durabilité remarquable. La fermeture à lacets permet un ajustement personnalisé, et le détail bijou sur le talon apporte une touche d''originalité. Convient à toutes celles qui recherchent un style intemporel sans compromis sur la qualité. Ces baskets incarnent l''esprit d''innovation et d''excellence d''Adidas, et s''imposent comme un choix incontournable pour compléter une garde-robe sophistiquée et tendance.', '120', '["35 1/3", "36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40", "42"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_gazelle_bold_ash_green_off_white_gum_16.jpg', '5', 'Femme', '[''vert'', ''noir'', ''blanc'']');